import{_ as a}from"./chunks/daily-2026-08-11-execution-authority-ordered-work-figure.CAfgnFyW.js";import{_ as o,C as r,o as d,c as i,E as c,a2 as n}from"./chunks/framework.Cm6XCzck.js";const C=JSON.parse('{"title":"数字员工需要显式的执行权边界","description":"","frontmatter":{"title":"数字员工需要显式的执行权边界","date":"2026-08-11","column":"digital-employee","category":"daily","summary":"定时到点、任务到达或进入队列，只能证明工作存在，不能证明已经获得执行权限。数字员工运行时应把任务到达、显式 Worker Claim、受治理 Running 状态与终态证据分开，并只通过明确的执行身份引入并发。","sources":["research/analysis/Q-20260811-01-execution-authority-ordered-work.md","research/reading/Q-20260811-01-ordered-local-work-queue.md"],"item_id":"Q-20260811-01","lifecycle":"Published","source_research_object":"research/analysis/Q-20260811-01-execution-authority-ordered-work.md","source_reading_result":"research/reading/Q-20260811-01-ordered-local-work-queue.md","cover":"/assets/covers/daily-2026-08-11-execution-authority-ordered-work.webp","visualization":"/assets/covers/daily-2026-08-11-execution-authority-ordered-work-figure.svg","visualization_decision":"Required — 独立编辑性题图 + 独立顺序执行通道解释图","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/digital-employee/2026-08-11-execution-authority-ordered-work.md","filePath":"zh/digital-employee/2026-08-11-execution-authority-ordered-work.md","lastUpdated":1786455324000}'),l={name:"zh/digital-employee/2026-08-11-execution-authority-ordered-work.md"};function s(u,e,h,p,m,b){const t=r("ArticleCover");return d(),i("div",null,[c(t,{image:"/assets/covers/daily-2026-08-11-execution-authority-ordered-work.webp",kicker:"数字员工 · 每日研究",title:"数字员工需要显式的执行权边界",summary:"定时到点、任务到达或进入队列，只能证明工作存在，不能证明已经获得执行权限。数字员工运行时应把任务到达、显式 Worker Claim、受治理 Running 状态与终态证据分开，并只通过明确的执行身份引入并发。",version:"Q-20260811-01",status:"Daily Runtime V5 · 2026-08-11",languageHref:"/en/digital-employee/2026-08-11-execution-authority-ordered-work",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="数字员工需要显式的执行权边界" tabindex="-1">数字员工需要显式的执行权边界 <a class="header-anchor" href="#数字员工需要显式的执行权边界" aria-label="Permalink to &quot;数字员工需要显式的执行权边界&quot;">​</a></h1><p>定时器已经触发、用户请求已经到达、任务已经进入队列，都不能自动推出“现在可以执行”。对于数字员工而言，真正关键的不是有没有排程，而是<strong>何时从‘工作存在’跨越到‘获得执行权’</strong>。</p><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>GitHub Copilot CLI 1.0.79 给出了一个很有价值的工程边界：当本地 Session 中已有任务正在执行时，新的 Prompt、Shell 命令和受支持的 Slash Command 可以继续到达，但会排队，并在当前任务结束后按顺序执行。同一个版本又单独支持多个并发 Session。这说明，顺序性不是“整个系统永远只能做一件事”，而是<strong>在明确的执行身份内部保持确定性顺序，再通过新的 Session / Worker 身份建立并发边界</strong>。</p><p>Research Center 的判断比“加一个队列”更严格：产品级数字员工运行时至少应该区分 <code>Received/Scheduled → Queued → Claimed → Running → Terminal</code>。其中 <strong>Claimed 才是执行权真正发生转移的边界</strong>。定时器唤醒只能证明需求已出现，Worker Claim 才证明某个执行主体获得了该通道的执行权限。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>主要一手证据来自 GitHub Copilot CLI 1.0.79 的维护者变更记录：</p><ul><li><a href="https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a" target="_blank" rel="noreferrer">https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a</a></li></ul><p>本次 Production 只消费 2026-08-11 当日已完成的 Research Object <code>Q-20260811-01</code> 及其 Reading Result。该来源能够证明已发布行为，但没有公开队列的数据结构、持久化格式或内部锁实现。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>这个版本同时出现三组相关机制。第一，新任务可以在当前任务执行期间到达，但只能排队等待，说明“到达”和“执行”是两个不同事件。第二，多个并发 Session 被明确支持，说明顺序性至少受到 Session Identity 的边界约束，而不是一个全局单队列。第三，由 Sandbox 导致的 MCP 与 Language Server 启动异常不再无限卡住，而是转化为有界失败，并且 <code>/sandbox policy</code> 可以显示实际生效的策略，而不只是配置意图。</p><p>这三点共同指向一个运行时原则：一个执行通道同一时刻应该只有一个明确的权威持有者；可能阻塞通道的启动依赖必须有有界失败；操作界面应该展示真正生效的执行策略和证据。</p><p><img src="'+a+'" alt="顺序执行通道与执行权边界"></p><p><em>图 1：Received 与 Scheduled 进入 Queued 后，只有显式 Worker Claim 才授予执行权。来源：Research Center 基于文中引用的一手资料综合绘制。</em></p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>运行事实</th><th>能证明什么</th><th>不能证明什么</th><th>证据类型</th></tr></thead><tbody><tr><td>定时器触发 / 请求到达</td><td>工作已经存在</td><td>可以立即修改状态或执行副作用</td><td>基于已发布排队行为的 Research Center 推断</td></tr><tr><td>已进入队列</td><td>工作已经获得顺序位置</td><td>Worker 所有权或真实进度</td><td>已发布行为 + 架构分析</td></tr><tr><td>Worker 显式 Claim</td><td>某个执行身份取得当前通道</td><td>业务已经成功</td><td>Research Center 架构建议</td></tr><tr><td>Running</td><td>Claimed 工作处于受租约保护的执行期</td><td>永久活跃或已经完成</td><td>Research Center 架构建议</td></tr><tr><td>终态证据</td><td>当前通道可以按治理规则释放</td><td>外部副作用天然 exactly-once</td><td>Research Center 架构建议</td></tr><tr><td>多 Session</td><td>存在显式并发身份边界</td><td>已解决跨 Session 资源仲裁</td><td>已发布能力；仲裁机制未知</td></tr></tbody></table><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>最危险的设计是把 <code>Running</code> 承担太多语义。如果 Scheduler 在真正 Worker 接单之前就把任务改成 Running，运营页面就可能显示“工作中”，但实际上没有任何执行主体在工作。反过来，如果下一个定时器仅因为时间到了就启动后续任务，系统又会出现两个班次同时执行，即使更早的班次还没有真正收口。</p><p>更可靠的模型应该拆开事实：<code>Wake Received</code> 只记录定时器确实启动；<code>Queued</code> 记录待处理意图；<code>Worker Claimed</code> 记录执行权；<code>Running</code> 是有时效的执行租约；显式 Terminal State 再决定当前通道是否可以释放给下一项工作。</p><p>并发应该建立在这个模型之上，而不是藏在一个执行通道内部。不同 Session、Worker 或 Workspace 可以拥有各自确定性的本地顺序；跨通道共享文件、外部系统或业务副作用，则必须再有显式同步或 Custody 规则。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对于数字员工平台，应把 Scheduler Receipt 和 Worker Claim 分开持久化，把固定时间仅视为 Wake Signal。Process Manager 只有在更早任务已经收口后，才可以把执行权授予下一项到期任务。</p><p>对于 CodeFlowMu，ADMIN/PM 任务到达和 Runtime 定时唤醒都应保持为 Queue Fact。UI 应明确区分 <code>Scheduled/Received</code>、<code>Waiting</code>、<code>Claimed</code>、<code>Running</code> 和终态，避免“执行槽已打开”被误解为“Worker 正在工作”。MCP 初始化等启动依赖需要独立超时和失败证据，不能无限占用 Running。</p><p>对于 TMPA，这一机制可以作为区分 Intent、Custody、Execution Authority 与 Terminal Evidence 的工程研究输入，但单一产品 Changelog 还不足以支持协议层面的队列或持久化规则。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>来源没有说明队列是否跨重启持久化，也没有定义容量、优先级、饥饿、去重或失败项如何影响后续队列。同时，多 Session 已被明确支持，但跨 Session 的文件系统和外部副作用仲裁没有被公开说明。因此可以借鉴的是<strong>顺序执行原则</strong>，而不能把它扩张成“Copilot CLI 已经实现了重启安全或 exactly-once 队列”。</p><h2 id="后续研究" tabindex="-1">后续研究 <a class="header-anchor" href="#后续研究" aria-label="Permalink to &quot;后续研究&quot;">​</a></h2><p>产品级数字员工应专门测试 Wake Receipt、队列持久化、Worker Claim、工具启动、终态落盘之间的崩溃点；同时还要定义取消、失败、部分外部副作用发生后，哪些终态能够释放下一项工作，以及一个数字员工到底应该只有一个全局通道，还是拥有多个 Role / Workspace Scope 的执行通道。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>题图位于文章头部，以一组等待中的执行舱和唯一获准开启的通道表现执行权边界；嵌入“观察”部分的解释图承担状态与顺序机制说明。两张图均为 Research Center 原创，不使用厂商图，也没有人为制造量化数据。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>GitHub，Copilot CLI 1.0.79 维护者 Changelog Commit <code>ef627e1baad937d3c8da45f8a5541c6fc3c97b6a</code>，2026-08-10：<a href="https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a" target="_blank" rel="noreferrer">https://github.com/github/copilot-cli/commit/ef627e1baad937d3c8da45f8a5541c6fc3c97b6a</a></li><li>Research Center Research Object：<code>research/analysis/Q-20260811-01-execution-authority-ordered-work.md</code></li><li>Research Center Reading Result：<code>research/reading/Q-20260811-01-ordered-local-work-queue.md</code></li></ol><blockquote><p>发布状态：已通过 Publication 门禁并正式发布；正文内容未对 Production Candidate 进行实质性改写。</p></blockquote>',33))])}const f=o(l,[["render",s]]);export{C as __pageData,f as default};
